-- Mục tiêu tháng của từng môi giới viên cho màn Tổng quan (docs/mcah-ke-hoach-tong-quan.md).
-- Mục tiêu công ty = tổng các dòng cùng tháng. Không xoá mềm: bỏ mục tiêu là đặt cả hai ô về NULL.
CREATE TABLE "kpi_target" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "user_id" INTEGER NOT NULL REFERENCES "user" ("id"),
  "month" DATE NOT NULL,
  "contracts" SMALLINT CHECK ("contracts" >= 0),
  "revenue_usd" decimal(12,2) CHECK ("revenue_usd" >= 0),
  "created_by" INTEGER,
  "updated_by" INTEGER,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  UNIQUE ("user_id", "month"),
  CONSTRAINT "kpi_target_month_check" CHECK (EXTRACT(DAY FROM "month") = 1)
);
CREATE TRIGGER "kpi_target_updated_at" BEFORE UPDATE ON "kpi_target" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

-- Đếm hợp đồng mới ký theo lần duyệt đầu tiên.
CREATE INDEX "contract_approval_log_action_idx" ON "contract_approval_log" ("action", "contract_id", "created_at");

-- Quyền mới kpi.view_all, kpi.manage: cấp cho vai trò đang có contract.approve.
INSERT INTO "role_permission" ("role_id", "permission")
SELECT "role_id", p.permission FROM "role_permission"
CROSS JOIN (VALUES ('kpi.view_all'), ('kpi.manage')) AS p (permission)
WHERE "role_permission"."permission" = 'contract.approve'
ON CONFLICT DO NOTHING;
